export function validateM78Route(url:string,method:string,company:string,mode:Mode){
 const u=new URL(url),root='/workspace-api/workspace/'+company;check(!u.hash&&!u.username&&!u.password)
 if(u.origin===AUTH){check(method==='POST'&&(u.pathname==='/auth/v1/token'&&u.search==='?grant_type=password'||u.pathname==='/auth/v1/logout'&&u.search==='?scope=local'));return}
