export function cleanM78Journal(events:M78Event[]){
 let attempt:M78Event|null=null,terminal=false,legacy=false;const names=new Set<string>(),intents=new Map<string,M78Event>(),outcomes=new Map<string,M78Event>(),verified=new Set<string>(),completed=new Set<string>(),auth=new Map<string,string>(),legacyAuth=new Map<number,{action:string;status:number|null}>()
 for(const e of events){
  if(e.kind==='provenance'){check(e.sequence===1&&attempt===null&&same(e.data.acceptedM77,M78_ACCEPTED_M77));continue}
  if(e.kind==='attempt_started'){check(attempt===null&&e.mode===e.data.mode&&!completed.has(e.mode)&&(e.mode==='baseline'?completed.size===0:completed.has('baseline'))&&(e.mode!=='revisit'||completed.has('exercise')));attempt=e;terminal=false;legacy=false;intents.clear();outcomes.clear();verified.clear();auth.clear();legacyAuth.clear();continue}
