  if(e.kind==='auth_intent'){check(['manager1','manager2','member','outsider'].includes(e.data.role)&&!auth.has(e.data.role));auth.set(e.data.role,'intent');continue}
  if(e.kind==='auth_outcome'){check(auth.get(e.data.role)==='intent'&&e.data.status===200&&e.data.tokenObserved===true&&e.data.subjectMatched===true);auth.set(e.data.role,'open');continue}
