  if(e.kind==='logout_outcome'){check(auth.get(e.data.role)==='closing'&&e.data.status===204);auth.set(e.data.role,'closed');continue}
  if(e.kind==='legacy_auth_intent'){check(!terminal&&Number.isSafeInteger(e.data.requestId)&&e.data.requestId===legacyAuth.size+1&&['login','logout'].includes(e.data.action));legacyAuth.set(e.data.requestId,{action:e.data.action,status:null});continue}
  if(e.kind==='legacy_auth_outcome'){const intent=legacyAuth.get(e.data.requestId);check(intent&&intent.action===e.data.action&&intent.status===null&&e.data.status===(intent.action==='login'?200:204));intent.status=e.data.status;continue}
  if(e.kind==='legacy_read_verified'){check(!legacy&&legacyAuth.size===8&&[...legacyAuth.values()].filter(v=>v.action==='login'&&v.status===200).length===4&&[...legacyAuth.values()].filter(v=>v.action==='logout'&&v.status===204).length===4&&e.data.unchanged===true&&e.data.applicationPostRequests===0&&e.data.allCreatedAuthSessionsClosed===true);legacy=true;continue}
  if(e.kind==='attempt_finished'){check(terminal&&legacy&&auth.size===4&&[...auth.values()].every(s=>s==='closed')&&e.data.unknownAuthSessions===0&&e.data.attemptSequence===attempt.sequence&&e.data.status==='passed'&&e.data.allCreatedAuthSessionsClosed===true&&e.data.applicationPostRequests===intents.size&&intents.size===(e.mode==='exercise'?M78_EXPECTED_POSTS:0)&&[...intents].every(([name,i])=>outcomes.has(name)&&(i.data.expected!==201||verified.has(name))));if(e.mode==='exercise')check([...intents.values()].filter(i=>i.data.expected===201).length===38&&['member','outsider','signed_out'].every(role=>intents.has('m78_'+role+'_write_refused')));completed.add(e.mode);attempt=null;continue}
