}
export function acceptedM77(text:string,company:string){check(hash(text)===M78_ACCEPTED_M77.journalSha256);const events=readM77Continuation(text,company);check(events.at(-1)?.sha256===M78_ACCEPTED_M77.headSha256&&events.some(e=>e.kind==='revisit_verified'));return events.find(e=>e.kind==='exercise_complete')!.data as {registers:any;downloads:any}}
export async function runM78Journey(input:M78JourneyInput,deps:M78Dependencies={}){
