 }
 const m78Downloads=async(reg:Awaited<ReturnType<typeof scope1>>)=>{const out:Record<string,{sha256:string;byteLength:number}>={};const retain=async(key:string,route:string,expected:string)=>{const value=await bytes(route,'member');check(value===expected);out[key]={sha256:hash(value),byteLength:Buffer.byteLength(value)}};for(const [family,stream]of [['process-screen',reg.process],['scope1-inventory',reg.inventory]]as const){for(const v of stream.versions){const base=root+'/'+family+'/'+v.streamId,exact=await decodeScope1Version(await get(base+'/versions/'+v.id,'member'),company);check(same(exact.version,v));await retain('version_'+v.id,base+'/versions/'+v.id+'/inventory-export',canonical(core(v)));check(same(await get(base+'/versions/'+v.id+'/proof','member'),exact.proof));for(const s of v.statements)await retain('statement_'+s.id,base+'/statements/'+s.id+'/download',s.text)}for(const meta of stream.reports){const base=root+'/'+family+'/'+meta.streamId+'/reports/'+meta.id,r=await decodeScope1Report(await get(base,'member'),company);await retain('html_'+r.id,base+'/download',r.html);await retain('snapshot_'+r.id,base+'/snapshot',r.snapshotJson);check(same(await get(base+'/proof','member'),(parseM78Json(r.snapshotJson)as any).proof))}}return out}
